scripts.script:
#!/usr/bin/env bash
set -euo pipefail
test "$(node --version)" = 'v22.23.1'
BUILD_TOOLS_DIRECTORY="$ANDROID_SDK_ROOT/build-tools/35.0.1" node --input-type=module <<'NODE'
import { createHash } from 'node:crypto';
import { mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import {
  CUSTODIAL_ANDROID_TOOLCHAIN_POLICY,
  resolveCustodialAndroidTools,
} from './mobile/scripts/verify-custodial-android-release.mjs';
const sha256 = (path) => createHash('sha256').update(readFileSync(path)).digest('hex');
const tools = resolveCustodialAndroidTools(process.env.BUILD_TOOLS_DIRECTORY);
const record = {
  schema_version: 1,
  codemagic_xcode_image: '26.2',
  android_build_tools_version: tools.version,
  toolchain_policy_sha256: CUSTODIAL_ANDROID_TOOLCHAIN_POLICY.sha256,
  files_sha256: {
    aapt2: sha256(tools.aapt2),
    apksigner: sha256(tools.apksigner),
    'lib/apksigner.jar': sha256(tools.apksignerJar),
    'source.properties': sha256(tools.sourceProperties),
    zipalign: sha256(tools.zipalign),
  },
};
mkdirSync('build/provenance', { recursive: true });
writeFileSync(
  'build/provenance/custodial-android-toolchain.json',
  `${JSON.stringify(record, null, 2)}\n`,
  { flag: 'wx' },
);
NODE

#!/usr/bin/env bash
set -euo pipefail
node --input-type=module <<'NODE'
import { createHash } from 'node:crypto';
import { lstatSync, mkdirSync, readFileSync, readdirSync, writeFileSync } from 'node:fs';
import { join, relative } from 'node:path';
import { createRuntimeAssetManifest } from './scripts/refresh-frontend-release-manifest.mjs';
const directory = 'mobile/mobile-dist';
const stored = JSON.parse(readFileSync(`${directory}/runtime-asset-manifest.json`, 'utf8'));
const build = JSON.parse(readFileSync(`${directory}/build.json`, 'utf8'));
const firebaseUtilPostinstallSha256 = createHash('sha256')
  .update(readFileSync('node_modules/@firebase/util/dist/postinstall.mjs'))
  .digest('hex');
if (firebaseUtilPostinstallSha256 !== '56e40adf04426e6b07df5d1ca7d4142a5b2c91ea9df5800589e357f9a2433252') {
  throw new Error('Dependency install policy probe differs from the reviewed lifecycle-free package source');
}
const actual = createRuntimeAssetManifest({ directory, edition: stored.edition, identity: stored });
if (JSON.stringify(stored) !== JSON.stringify(actual)) throw new Error('Runtime asset manifest does not match built bytes');
if (stored.edition !== process.env.MZ_APP_EDITION || build.edition !== process.env.MZ_APP_EDITION) throw new Error('Edition provenance mismatch');
if (process.env.CM_COMMIT && stored.source_commit !== process.env.CM_COMMIT.toLowerCase()) throw new Error('Codemagic source commit mismatch');
const files = [];
const walk = (path) => {
  for (const name of readdirSync(path).sort()) {
    const file = join(path, name);
    const stat = lstatSync(file);
    if (stat.isSymbolicLink()) throw new Error(`Unexpected symlink: ${file}`);
    if (stat.isDirectory()) walk(file);
    else if (stat.isFile()) files.push(file);
  }
};
walk(directory);
mkdirSync('build/provenance', { recursive: true });
const checksums = files.map((file) => `${createHash('sha256').update(readFileSync(file)).digest('hex')}  ${relative(directory, file).replaceAll('\\', '/')}`).join('\n');
writeFileSync(`build/provenance/${process.env.MZ_APP_EDITION}-web.sha256`, `${checksums}\n`);
writeFileSync(`build/provenance/${process.env.MZ_APP_EDITION}-build.json`, `${JSON.stringify({
  ...build,
  node: process.version,
  npm: '11.17.0',
  dependency_install_policy: 'npm-ci-ignore-scripts-v1',
  firebase_util_postinstall_sha256: firebaseUtilPostinstallSha256,
  codemagic_build_id: process.env.CM_BUILD_ID || null,
}, null, 2)}\n`);
NODE
